 1 │ /**
 2 │  * A minimal validating JSON blob store, mirroring `Storage.ts`'s
 3 │  * `IStorage`/`LocalStorageAdapter`/`InMemoryStorage` split. Unlike
 4 │  * `IStorage` (which always returns *some* `LearnerState`, defaulting to
 5 │  * `INITIAL_LEARNER_STATE`), `JsonStore.load()` is three-state: a store that
 6 │  * has never been written to ("empty") must stay distinguishable from one
 7 │  * whose stored value is unreadable ("corrupt") — the caller decides what
 8 │  * each means, this layer only reports which happened.
 9 │  */
10 │ export type JsonStoreLoadResult<T> =
11 │ 	| { readonly status: "empty" }
12 │ 	| { readonly status: "ok"; readonly value: T }
13 │ 	| { readonly status: "corrupt" };
14 │ 
15 │ export type JsonStoreSaveResult =
16 │ 	| { readonly status: "ok" }
17 │ 	| { readonly status: "failed" };
18 │ 
19 │ /** Narrows `unknown` to `T`, used to reject a parsed-but-wrong-shape value. */
20 │ export type JsonShapeGuard<T> = (value: unknown) => value is T;
21 │ 
22 │ export interface JsonStore<T> {
23 │ 	load(): JsonStoreLoadResult<T>;
24 │ 	save(value: T): JsonStoreSaveResult;
25 │ }
26 │ 
27 │ /**
28 │  * Backed by `localStorage` under a caller-supplied `key`. Never throws:
29 │  * invalid JSON, a value failing `isValidShape`, `localStorage` being
30 │  * unavailable, or `setItem` throwing (e.g. `QuotaExceededError`) are all
31 │  * surfaced as typed results.
32 │  */
33 │ export class LocalStorageJsonStore<T> implements JsonStore<T> {
34 │ 	constructor(
35 │ 		private readonly key: string,
36 │ 		private readonly isValidShape: JsonShapeGuard<T>,
37 │ 	) {}
38 │ 
39 │ 	load(): JsonStoreLoadResult<T> {
40 │ 		if (typeof localStorage === "undefined") return { status: "empty" };
41 │ 		const raw = localStorage.getItem(this.key);
42 │ 		if (raw === null) return { status: "empty" };
43 │ 
44 │ 		let parsed: unknown;
45 │ 		try {
46 │ 			parsed = JSON.parse(raw);
47 │ 		} catch {
48 │ 			return { status: "corrupt" };
49 │ 		}
50 │ 
51 │ 		if (!this.isValidShape(parsed)) return { status: "corrupt" };
52 │ 		return { status: "ok", value: parsed };
53 │ 	}
54 │ 
55 │ 	save(value: T): JsonStoreSaveResult {
56 │ 		if (typeof localStorage === "undefined") return { status: "ok" };
57 │ 		try {
58 │ 			localStorage.setItem(this.key, JSON.stringify(value));
59 │ 			return { status: "ok" };
60 │ 		} catch {
61 │ 			return { status: "failed" };
62 │ 		}
63 │ 	}
64 │ }
65 │ 
66 │ /** In-memory equivalent, for tests and non-browser callers. */
67 │ export class InMemoryJsonStore<T> implements JsonStore<T> {
68 │ 	private value: T | undefined;
69 │ 
70 │ 	load(): JsonStoreLoadResult<T> {
71 │ 		return this.value === undefined
72 │ 			? { status: "empty" }
73 │ 			: { status: "ok", value: this.value };
74 │ 	}
75 │ 
76 │ 	save(value: T): JsonStoreSaveResult {
77 │ 		this.value = value;
78 │ 		return { status: "ok" };
79 │ 	}
80 │ }

